using System;
using System.Threading.Tasks;
using UnityEngine;

namespace MotionBricks
{
    /// <summary>
    /// Plays motion generated by MotionBricks and keeps the recorded history that the next
    /// generation uses as context. Ported from <c>motionbricks/runtime/motion_player.py</c>.
    /// </summary>
    public sealed class GeneratedSomaMotionPlayer : IDisposable
    {
        private readonly SomaGenerator _generator;
        private readonly SomaSkeleton _skeleton;
        private readonly SomaPoseToken _context;
        private SomaPoseToken _target;
        private SomaAnimationBuffer _output;
        private readonly SomaMotionRecorder _history;
        private SomaAnimationBuffer _backgroundOutput;

        private Pose[] _currentPose;
        private float[] _footContacts = new float[MbContract.FootContactCount];
        private float _playbackTime;
        private int _transitionEarlyByFrames;
        private Vector3[] _generatedRootPositions = Array.Empty<Vector3>();
        private bool _generationInFlight;
        private Task _backgroundTask;
        private Task<int> _completedGeneration;

        /// <summary>Playback time of the transition point, in seconds.</summary>
        public float PlaybackDuration
        {
            get
            {
                var endFrame = Math.Max(0, _output.NumFrames - 1 - _transitionEarlyByFrames);
                return endFrame / _output.SampleRate;
            }
        }

        /// <summary>Seconds until the transition point. Sampling can continue past it.</summary>
        public float TimeToTransition => Math.Max(0f, PlaybackDuration - _playbackTime);

        /// <summary>Time played so far, in seconds.</summary>
        public float PlaybackTime => _playbackTime;

        /// <summary>Number of valid frames in the current motion.</summary>
        public int NumFrames => _output.NumFrames;

        /// <summary>True while a background generation runs.</summary>
        public bool GenerationInFlight => _generationInFlight;

        /// <summary>The four foot contacts of the last sampled frame.</summary>
        public float[] FootContacts => _footContacts;

        /// <summary>The pose shown by the last sample.</summary>
        public Pose[] CurrentPose => _currentPose;

        public GeneratedSomaMotionPlayer(ISomaInferenceBackend backend, SomaSkeleton skeleton, int historyCapacity = 32)
        {
            _generator = new SomaGenerator(backend, skeleton);
            _skeleton = skeleton;
            _context = new SomaPoseToken(skeleton);
            _target = new SomaPoseToken(skeleton);
            _output = new SomaAnimationBuffer(skeleton);
            _backgroundOutput = new SomaAnimationBuffer(skeleton);
            _history = new SomaMotionRecorder(skeleton, historyCapacity);
            _currentPose = new Pose[skeleton.NumJoints];
        }

        /// <summary>
        /// Fills every history slot and the context with one pose.
        /// </summary>
        public void SeedHistoryFromPose(Pose[] pose)
        {
            _history.Fill(pose);
            RefreshContext();
        }

        /// <summary>Updates the context poses from the recorded playback history.</summary>
        public void RefreshContext()
        {
            _context.UpdateFromRecorder(_history);
        }

        /// <summary>
        /// Generates toward a target from the recorded history, then restarts playback.
        /// </summary>
        /// <param name="targetPoses">The target's poses, laid out as [pose, joint].</param>
        /// <param name="numJoints">Joints per pose.</param>
        /// <param name="inferenceParams">Generation settings of the target.</param>
        /// <param name="config">Other generation settings. Null uses the defaults.</param>
        public void Generate(
            Pose[] targetPoses,
            int numJoints,
            TargetPoseInferenceParams inferenceParams,
            MotionBricksInferenceConfig config = null)
        {
            var generationConfig = config != null ? config.Clone() : new MotionBricksInferenceConfig();
            if (inferenceParams.AllowedTokenCounts != null)
            {
                generationConfig.AllowedTokenCounts = new System.Collections.Generic.List<int>(inferenceParams.AllowedTokenCounts);
            }

            var numPoses = Mathf.Clamp(inferenceParams.NumPosesToUse, 1, MbContract.PosesPerToken);
            _target.UpdateFromPoses(targetPoses, numJoints, numPoses);
            _transitionEarlyByFrames = Mathf.Max(0, inferenceParams.TransitionEarlyByFrames);
            RefreshContext();

            _generator.Generate(_context, _target, _output, generationConfig);
            _playbackTime = 0f;
            _generatedRootPositions = _output.RootPositions();
        }

        /// <summary>
        /// Generates on a background thread from a snapshot of the recorded history, then swaps the
        /// result in on the main thread. The recording continues while the model runs, so the next
        /// generation sees a newer context.
        /// </summary>
        /// <returns>False when a generation is already running.</returns>
        public bool TryGenerateAsync(
            Pose[] targetPoses,
            int numJoints,
            TargetPoseInferenceParams inferenceParams,
            MotionBricksInferenceConfig config = null)
        {
            if (_generationInFlight)
            {
                return false;
            }

            var generationConfig = config != null ? config.Clone() : new MotionBricksInferenceConfig();
            if (inferenceParams.AllowedTokenCounts != null)
            {
                generationConfig.AllowedTokenCounts = new System.Collections.Generic.List<int>(inferenceParams.AllowedTokenCounts);
            }

            var numPoses = Mathf.Clamp(inferenceParams.NumPosesToUse, 1, MbContract.PosesPerToken);
            var targetCopy = new Pose[numPoses * numJoints];
            Array.Copy(targetPoses, targetCopy, targetCopy.Length);

            var snapshot = _history.Snapshot();
            var contextPoses = new Pose[MbContract.PosesPerToken * numJoints];
            snapshot.SampleInto(contextPoses, MbContract.PosesPerToken, MbContract.SampleRate);

            _generationInFlight = true;
            var generation = _generator;
            var output = _backgroundOutput;
            var transitionEarlyByFrames = Mathf.Max(0, inferenceParams.TransitionEarlyByFrames);

            _completedGeneration = Task.Run(() =>
            {
                var context = new SomaPoseToken(_skeleton);
                context.UpdateFromPoses(contextPoses, numJoints, MbContract.PosesPerToken);
                var target = new SomaPoseToken(_skeleton);
                target.UpdateFromPoses(targetCopy, numJoints, numPoses);
                generation.Generate(context, target, output, generationConfig);
                return transitionEarlyByFrames;
            });

            _backgroundTask = _completedGeneration;
            return true;
        }

        /// <summary>
        /// Swaps in a finished background generation. Call this from the main thread, for example in
        /// <c>Update</c>, so the playback state changes on the thread that samples it.
        /// </summary>
        /// <returns>True when a finished generation was swapped in.</returns>
        public bool PollBackgroundGeneration()
        {
            if (!_generationInFlight || _completedGeneration == null)
            {
                return false;
            }

            if (!_completedGeneration.IsCompleted)
            {
                return false;
            }

            if (_completedGeneration.IsFaulted)
            {
                Debug.LogException(_completedGeneration.Exception?.GetBaseException());
                _generationInFlight = false;
                _completedGeneration = null;
                return false;
            }

            var previous = _output;
            _output = _backgroundOutput;
            _backgroundOutput = previous;
            _transitionEarlyByFrames = _completedGeneration.Result;
            _playbackTime = 0f;
            _generatedRootPositions = _output.RootPositions();
            _generationInFlight = false;
            _completedGeneration = null;
            return true;
        }

        /// <summary>
        /// Advances playback, then writes the pose and its foot contacts.
        /// </summary>
        public void Sample(float deltaTime, Pose[] destinationPose, float[] destinationFootContacts)
        {
            if (float.IsNaN(deltaTime) || float.IsInfinity(deltaTime) || deltaTime < 0f)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(deltaTime), deltaTime, "deltaTime must be finite and non-negative.");
            }

            _playbackTime += deltaTime;
            var identity = new Pose(Vector3.zero, Quaternion.identity);
            _output.Sample(_playbackTime, destinationPose, identity);
            _output.SampleFootContacts(_playbackTime, destinationFootContacts);
            Array.Copy(destinationPose, _currentPose, destinationPose.Length);
            Array.Copy(destinationFootContacts, _footContacts, destinationFootContacts.Length);
        }

        /// <summary>
        /// Records an evaluated character pose for the next generation context.
        /// </summary>
        public void RecordPose(float deltaTime, Pose[] pose)
        {
            _history.Record(deltaTime, pose);
        }

        /// <summary>Returns the interpolated generated root position at the playback time.</summary>
        public Vector3 CurrentRootPosition()
        {
            if (_generatedRootPositions.Length == 0)
            {
                return Vector3.zero;
            }

            MbPose.FrameIndexFromTime(
                _playbackTime, _output.SampleRate, _generatedRootPositions.Length,
                out var frame, out var nextFrame, out var blend);
            return Vector3.LerpUnclamped(_generatedRootPositions[frame], _generatedRootPositions[nextFrame], blend);
        }

        /// <summary>Returns the generator, for diagnostics such as stage timings.</summary>
        public SomaGenerator Generator => _generator;

        public void Dispose()
        {
            _backgroundTask?.Wait();
        }
    }
}
